import json,re,collections,itertools
rows=json.load(open('$SP/rows3.json'))
R={r['num']:r for r in rows}
pth=re.compile(r'((?:[\w\-]+/)+[\w\-.]+\.(?:fss|fsi|test|sh|py))')
def paths(r):
    s=set()
    for m in pth.finditer(r['repro']): s.add(m.group(1))
    return s
P={n:paths(r) for n,r in R.items()}
pc=collections.Counter(p for s in P.values() for p in s)
