pairs=collections.defaultdict(set)
for p,c in pc.items():
    if c>=2:
        ns=[n for n,s in P.items() if p in s]
        for a,b in itertools.combinations(sorted(ns),2): pairs[(a,b)].add(p)
print('pairs sharing a full reproducer path',len(pairs))
# strong: share >=2 paths, or the only path of both
strong=[(k,v) for k,v in pairs.items() if len(v)>=2 or (len(P[k[0]])==1 and len(P[k[1]])==1)]
print('strong (>=2 shared paths or each cites a single path and it is shared)',len(strong))
json.dump([[k[0],k[1],sorted(v)] for k,v in strong],open('$SP/strong_paths.json','w'))
par={}
def f(x):
    par.setdefault(x,x)
    while par[x]!=x:
        par[x]=par[par[x]];x=par[x]
    return x
for k,v in strong: par[f(k[0])]=f(k[1])
comp=collections.defaultdict(list)
for x in list(par): comp[f(x)].append(x)
print('components',len(comp),'rows',sum(len(v) for v in comp.values()))
for c,m in sorted(comp.items(),key=lambda kv:-len(kv[1]))[:12]: print(sorted(m))
EOF

